# Audit trail: (label, left, top, right, bottom) for every text box and
# pin drawn, filled in by draw().  A separate script checks them.
TRACE = []


def record(label, x0, y0, x1, y1):
    TRACE.append((label, x0, y0, x1, y1))


def _sine(x):
    """Sine from a Taylor series (math is deliberately not imported)."""
    while x > 3.141592653589793:
        x -= 6.283185307179586
    while x < -3.141592653589793:
        x += 6.283185307179586
    x2 = x * x
    return x * (1.0 - x2 / 6.0 + x2 * x2 / 120.0 - x2 * x2 * x2 / 5040.0)


def _cosine(x):
    """Cosine from a Taylor series."""
    while x > 3.141592653589793:
        x -= 6.283185307179586
    while x < -3.141592653589793:
        x += 6.283185307179586
    x2 = x * x
    return 1.0 - x2 / 2.0 + x2 * x2 / 24.0 - x2 * x2 * x2 / 720.0


