def look_up(font, ch):
    """Return (advance, width, height, y-offset, hex) for a character."""
    g = font.get(ch)
    if g is None:
        g = font.get("?", (8, 0, 0, 0, ""))
    return g


def measure(font, text, track=0):
    """Pixel width of a string in a baked font, with letter tracking."""
    total = 0
    for ch in text:
        total += look_up(font, ch)[0] + track
    if text:
        total -= track
    return total


def wrap(font, text, max_w, track=0):
    """Greedy word wrap; returns the lines that fit inside max_w."""
    out = []
    for para in text.split("\n"):
        words = para.split(" ")
        cur = ""
        for word in words:
            trial = word if not cur else cur + " " + word
            if measure(font, trial, track) <= max_w or not cur:
                cur = trial
            else:
                out.append(cur)
                cur = word
        if cur or not out:
            out.append(cur)
    return out


def shorten_label(num, place, source, font_label, font_src, max_w):
    """Trim a card's source (then its region suffix) so the place label
    and the source never overlap inside the card; keep at least a 12 px
    gap between them."""
    label = "%d \u00b7 %s" % (num, place)
    src = source
    while (measure(font_label, label) + 12 + measure(font_src, src) > max_w
           and " " in src):
        src = src.rsplit(" ", 1)[0]
    if src.endswith(" /"):
        src = src[:-2]
    if (measure(font_label, label) + 12 + measure(font_src, src) > max_w
            and " - " in place):
        place = place.split(" - ")[0]
        label = "%d \u00b7 %s" % (num, place)
    while (measure(font_label, label) + 12 + measure(font_src, src) > max_w
           and " " in src):
        src = src.rsplit(" ", 1)[0]
    if src.endswith(" /"):
        src = src[:-2]
    return label, src


class Sheet:
    """An RGB pixel buffer with the few drawing primitives the page needs."""

    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.buf = bytearray(bg * (w * h))

    def _pos(self, x, y):
        return (y * self.w + x) * 3

    def put(self, x, y, colour):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = self._pos(x, y)
            self.buf[i:i + 3] = bytes(colour)

    def blend(self, x, y, colour, cover):
        """Blend a colour over the pixel; cover is a 4-bit level, 0..15."""
        if cover <= 0 or not (0 <= x < self.w and 0 <= y < self.h):
            return
        if cover >= 15:
            self.put(x, y, colour)
            return
        i = self._pos(x, y)
        b = self.buf
        for k in range(3):
            b[i + k] = (b[i + k] * (15 - cover) + colour[k] * cover) // 15

    def fill(self, x, y, w, h, colour):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(colour) * (x1 - x0)
        for yy in range(y0, y1):
            i = self._pos(x0, yy)
            self.buf[i:i + len(row)] = row

    def frame(self, x, y, w, h, colour, lw=1):
        self.fill(x, y, w, lw, colour)
        self.fill(x, y + h - lw, w, lw, colour)
        self.fill(x, y, lw, h, colour)
        self.fill(x + w - lw, y, lw, h, colour)

    def hbar(self, x, y, w, colour, lw=1):
        self.fill(x, y, w, lw, colour)

    def vbar(self, x, y, h, colour, lw=1):
        self.fill(x, y, lw, h, colour)

    def segment(self, x0, y0, x1, y1, colour, lw=1):
        """Bresenham line, lw pixels thick."""
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        x, y = x0, y0
        while True:
            self.fill(x - lw // 2, y - lw // 2, lw, lw, colour)
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x += sx
            if e2 < dx:
                err += dx
                y += sy

    def disc(self, cx, cy, r, colour):
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            span = int((r * r - dy * dy) ** 0.5)
            self.fill(cx - span, yy, span * 2 + 1, 1, colour)

    def hoop(self, cx, cy, r, colour, lw=1):
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            outer = int((r * r - dy * dy) ** 0.5)
            inner_r = r - lw
            if abs(dy) < inner_r:
                inner = int((inner_r * inner_r - dy * dy) ** 0.5)
                self.fill(cx - outer, yy, outer - inner, 1, colour)
                self.fill(cx + inner + 1, yy, outer - inner, 1, colour)
            else:
                self.fill(cx - outer, yy, outer * 2 + 1, 1, colour)

    def fill_poly(self, pts, colour):
        """Even-odd scanline fill of a polygon given as [(x, y), ...]."""
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        y0, y1 = max(0, min(ys)), min(self.h - 1, max(ys))
        n = len(pts)
        for y in range(y0, y1 + 1):
            xs = []
            for i in range(n):
                xa, ya = pts[i]
                xb, yb = pts[(i + 1) % n]
                if (ya <= y < yb) or (yb <= y < ya):
                    t = (y - ya) / (yb - ya)
                    xs.append(xa + t * (xb - xa))
            xs.sort()
            for j in range(0, len(xs) - 1, 2):
                xa = int(xs[j] + 0.5)
                xb = int(xs[j + 1] + 0.5)
                if xb >= xa:
                    self.fill(xa, y, xb - xa + 1, 1, colour)

    def blit(self, x, y, font, ch, colour):
        """Blit one baked glyph with its baseline at y."""
        adv, w, h, off, hexs = look_up(font, ch)
        if w == 0 or h == 0:
            return
        top = y + off
        # One hex digit per pixel, in row-major order.
        pos = 0
        for row in range(h):
            for col in range(w):
                cov = int(hexs[pos], 16)
                pos += 1
                if cov:
                    self.blend(x + col, top + row, colour, cov)

    def write(self, x, y_baseline, font, s, colour, track=0, align="left"):
        """Draw text with its baseline at y_baseline. Returns end x."""
        if align == "center":
            x -= measure(font, s, track) // 2
        elif align == "right":
            x -= measure(font, s, track)
        cx = x
        for ch in s:
            adv = look_up(font, ch)[0]
            self.blit(cx, y_baseline, font, ch, colour)
            cx += adv + track
        return cx

    def block(self, x, y_top, font, lines, colour, leading, track=0):
        """Draw pre-wrapped lines starting at y_top (first baseline)."""
        y = y_top
        for ln in lines:
            self.write(x, y, font, ln, colour, track=track)
            y += leading
        return y


def save_png(sheet, path):
    """Encode the sheet as a PNG with per-row adaptive filtering."""
    w, h = sheet.w, sheet.h
    raw = bytearray()
    prev = bytes(w * 3)
    buf = sheet.buf
    for y in range(h):
        row = bytes(buf[y * w * 3:(y + 1) * w * 3])
        best = None
        best_data = None
        for f in (0, 1, 2, 4):
            if f == 0:
                data = row
            elif f == 1:
                # Sub: the predictor is the ORIGINAL byte 3 back, so
                # build from the unfiltered row, never in place.
                data = bytes((row[i] - row[i - 3]) & 255 if i >= 3 else row[i]
                             for i in range(len(row)))
            elif f == 2:
                data = bytes((row[i] - prev[i]) & 255 for i in range(len(row)))
            else:
                # Paeth.
                data = bytearray(len(row))
                for i in range(len(row)):
                    a = row[i - 3] if i >= 3 else 0
                    b = prev[i]
                    cc = prev[i - 3] if i >= 3 else 0
                    p = a + b - cc
                    pa, pb, pc = abs(p - a), abs(p - b), abs(p - cc)
                    pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else cc)
                    data[i] = (row[i] - pr) & 255
                data = bytes(data)
            comp = zlib.compress(bytes([f]) + data, 1)
            if best is None or len(comp) < best:
                best = len(comp)
                best_data = bytes([f]) + data
        raw += best_data
        prev = row
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", ihdr)
    png += chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    with open(path, "wb") as fh:
        fh.write(png)
    return len(png)


