# Each draws inside the box (x, y, w, h); shapes are placed with
# fractions of w and h so the same picture works in a lead card and in
# a small card.
# ---------------------------------------------------------------------------

def paint_picture(s, kind, x, y, w, h):
    if kind == "tanker":
        # Two tankers on a strait, a mine below, a burst above one hull.
        s.fill(x, y, w, h, SKY)
        s.fill(x, y + h - 16, w, 16, (40, 90, 130))
        for wx in range(6, w - 4, 18):
            s.fill(x + wx, y + h - 12, 9, 2, WHITE)
        s.fill(x + 8, y + h - 34, w // 2 - 6, 12, (30, 30, 34))
        s.fill(x + 8, y + h - 40, 10, 6, (30, 30, 34))
        s.fill(x + w // 2 + 8, y + h - 30, w // 2 - 16, 10, (60, 60, 66))
        s.fill(x + w // 2 + 8, y + h - 36, 8, 6, (60, 60, 66))
        cx, cy = x + w // 4, y + h // 3 + 2
        s.fill_poly([(cx, cy - 8), (cx + 3, cy - 2), (cx + 9, cy),
                     (cx + 3, cy + 3), (cx, cy + 8), (cx - 3, cy + 3),
                     (cx - 9, cy), (cx - 3, cy - 2)], (240, 120, 40))
        s.disc(cx, cy, 3, RED)
        s.disc(x + w - 20, y + 10, 4, INK)
        s.segment(x + w - 20, y + 10, x + w - 14, y + 4, INK, 1)
        s.segment(x + w - 20, y + 10, x + w - 26, y + 4, INK, 1)
        s.segment(x + w - 20, y + 10, x + w - 20, y + 3, INK, 1)
    elif kind == "rocket":
        # A rocket climbing past stars toward a small station.
        s.fill(x, y, w, h, (24, 30, 58))
        for sx, sy in ((10, 8), (w - 14, 12), (w // 2, 6), (16, 26),
                       (w - 26, 30)):
            s.disc(x + sx, y + sy, 1, WHITE)
        cx = x + w // 2 - 6
        cy = y + h - 18
        s.fill_poly([(cx + 6, y + 6), (cx + 12, y + 18), (cx + 12, cy),
                     (cx, cy), (cx, y + 18)], WHITE)
        s.fill_poly([(cx + 6, y + 6), (cx + 2, y + 14), (cx + 10, y + 14)],
                    RED)
        s.fill_poly([(cx, y + 26), (cx - 6, cy + 4), (cx, cy)], RED)
        s.fill_poly([(cx + 12, y + 26), (cx + 18, cy + 4), (cx + 12, cy)],
                    RED)
        s.fill_poly([(cx + 4, cy), (cx + 8, cy), (cx + 6, cy + 10)],
                    (240, 160, 40))
        s.fill(x + w - 34, y + 8, 26, 8, GOLD)
        s.frame(x + w - 34, y + 8, 26, 8, INK, 1)
        s.fill(x + w - 22, y + 16, 2, 6, INK)
        s.disc(x + w - 12, y + 12, 3, (90, 140, 190))
    elif kind == "siege":
        # A supermarket front with an awning, a shield at the door.
        s.fill(x, y, w, h, (214, 226, 238))
        s.fill(x + 6, y + 10, w - 12, h - 20, WHITE)
        s.frame(x + 6, y + 10, w - 12, h - 20, INK, 1)
        for i in range(5):
            col = RED if i % 2 == 0 else WHITE
            s.fill(x + 8 + i * (w - 16) // 5, y + 12,
                   (w - 16) // 5, 8, col)
        s.fill(x + w // 2 - 12, y + h - 22, 24, 12, NAVY)
        s.frame(x + w // 2 - 12, y + h - 22, 24, 12, INK, 1)
        s.fill(x + 14, y + 26, w // 4, 10, (90, 140, 190))
        s.fill(x + w - 14 - w // 4, y + 26, w // 4, 10, (90, 140, 190))
        s.disc(x + w - 18, y + h - 14, 7, GOLD)
        s.fill(x + w - 21, y + h - 17, 6, 6, WHITE)
    elif kind == "strike":
        # A dark sky, a burst over rooftops, falling debris.
        s.fill(x, y, w, h, (52, 52, 60))
        s.fill(x, y + h - 14, w, 14, (30, 30, 36))
        for bx in (8, w // 2 - 10, w - 28):
            s.fill(x + bx, y + h - 26, 20, 12, (70, 70, 78))
        cx, cy = x + w // 2, y + 16
        s.fill_poly([(cx, cy - 12), (cx + 4, cy - 4), (cx + 13, cy - 2),
                     (cx + 5, cy + 3), (cx + 8, cy + 11), (cx, cy + 6),
                     (cx - 8, cy + 11), (cx - 5, cy + 3), (cx - 13, cy - 2),
                     (cx - 4, cy - 4)], (240, 180, 60))
        s.disc(cx, cy, 4, RED)
        for dx, dy in ((-18, 8), (20, 6), (-8, 18), (14, 20)):
            s.disc(x + w // 2 + dx, y + dy, 2, (200, 200, 200))
    elif kind == "expel":
        # An office block, its door open, a suitcase on the step, an
        # arrow pointing out.
        s.fill(x, y, w, h, (200, 220, 235))
        s.fill(x + w // 2 - 30, y + 6, 60, h - 16, WHITE)
        s.frame(x + w // 2 - 30, y + 6, 60, h - 16, INK, 1)
        for i in range(3):
            s.fill(x + w // 2 - 22, y + 12 + i * 10, 16, 7, (90, 130, 170))
            s.fill(x + w // 2 + 6, y + 12 + i * 10, 16, 7, (90, 130, 170))
        s.fill(x + w // 2 - 7, y + h - 20, 14, 10, DARKRED)
        s.fill(x + 10, y + h - 14, 18, 10, (150, 90, 40))
        s.frame(x + 10, y + h - 14, 18, 10, INK, 1)
        s.fill(x + 16, y + h - 18, 6, 4, (150, 90, 40))
        s.segment(x + w - 34, y + h - 9, x + w - 10, y + h - 9, RED, 3)
        s.fill_poly([(x + w - 10, y + h - 9), (x + w - 18, y + h - 14),
                     (x + w - 18, y + h - 4)], RED)
    elif kind == "mine":
        # Rain over a hillside, a shaft mouth, water rising inside.
        s.fill(x, y, w, h, (180, 190, 180))
        for rx in range(8, w - 4, 14):
            s.segment(x + rx, y + 4, x + rx - 3, y + 12, (90, 120, 160), 2)
        s.fill_poly([(x, y + h), (x + w // 3, y + h // 3),
                     (x + 2 * w // 3, y + h)], (120, 150, 110))
        s.fill_poly([(x + w // 3, y + h), (x + 2 * w // 3, y + h // 4),
                     (x + w, y + h)], (100, 135, 95))
        s.fill(x + w // 2 - 14, y + h - 26, 28, 26, (40, 40, 44))
        s.frame(x + w // 2 - 14, y + h - 26, 28, 26, INK, 1)
        s.fill(x + w // 2 - 14, y + h - 10, 28, 10, (60, 110, 160))
        s.fill(x + 8, y + h - 8, 20, 8, (90, 70, 40))
        s.fill(x + w - 28, y + h - 8, 20, 8, (90, 70, 40))
    elif kind == "wage":
        # A factory beside a stack of banknotes and a rising arrow.
        s.fill(x, y, w, h, (232, 222, 196))
        s.fill(x + 8, y + h - 20, w // 2 - 8, 20, (140, 90, 70))
        s.fill(x + 10, y + h - 28, 8, 8, (140, 90, 70))
        s.fill(x + 22, y + h - 32, 8, 12, (140, 90, 70))
        s.fill(x + 34, y + h - 28, 8, 8, (140, 90, 70))
        for wy in (0, 5, 10):
            s.fill(x + w - 44, y + h - 22 - wy, 34, 4, (60, 140, 90))
            s.frame(x + w - 44, y + h - 22 - wy, 34, 4, INK, 1)
        s.disc(x + w - 27, y + h - 20, 3, GOLD)
        pts = [(x + w - 48, y + 16), (x + w - 30, y + 10),
               (x + w - 12, y + 6)]
        for i in range(len(pts) - 1):
            s.segment(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1],
                      GREEN, 2)
        s.fill_poly([(x + w - 12, y + 6), (x + w - 22, y + 6),
                     (x + w - 12, y + 16)], GREEN)
    elif kind == "tower":
        # A tall tower, smoke at its crown, a small flame at mid-height.
        s.fill(x, y, w, h, (210, 214, 226))
        s.fill(x + w // 2 - 12, y + 8, 24, h - 16, (150, 155, 170))
        s.frame(x + w // 2 - 12, y + 8, 24, h - 16, INK, 1)
        for ry in range(14, h - 12, 10):
            s.fill(x + w // 2 - 8, y + ry, 16, 4, (90, 130, 170))
        s.disc(x + w // 2 - 8, y + 6, 5, (150, 150, 145))
        s.disc(x + w // 2 + 4, y + 4, 4, (170, 170, 165))
        s.fill_poly([(x + w // 2 + 14, y + h // 2),
                     (x + w // 2 + 20, y + h // 2 + 10),
                     (x + w // 2 + 8, y + h // 2 + 10)], (240, 120, 40))
        s.disc(x + w // 2 + 14, y + h // 2 + 8, 3, RED)
        s.fill(x, y + h - 8, w, 8, (120, 125, 135))
    elif kind == "port":
        # Harbour cranes over containers and a ship at the quay.
        s.fill(x, y, w, h, SKY)
        s.fill(x, y + h - 12, w, 12, (60, 110, 150))
        s.fill(x + 10, y + 10, 4, h - 26, INK)
        s.fill(x + 10, y + 10, 26, 4, INK)
        s.fill(x + 30, y + 14, 6, 8, RED)
        s.segment(x + 10, y + 14, x + 30, y + 28, INK, 1)
        s.fill(x + w - 34, y + 10, 4, h - 26, INK)
        s.fill(x + w - 34, y + 10, 22, 4, INK)
        for cx, col in ((w // 2 - 22, RED), (w // 2 - 6, GOLD),
                        (w // 2 + 10, BLUE)):
            s.fill(x + cx, y + h - 26, 14, 10, col)
            s.frame(x + cx, y + h - 26, 14, 10, INK, 1)
        s.fill(x + 8, y + h - 26, w // 2, 8, (40, 40, 46))
        s.fill(x + 12, y + h - 30, 8, 4, WHITE)
    elif kind == "toll":
        # A ledger page with tallies and a long red line of loss.
        s.fill(x, y, w, h, (222, 214, 196))
        s.fill(x + w // 2 - 30, y + 4, 60, h - 8, WHITE)
        s.frame(x + w // 2 - 30, y + 4, 60, h - 8, INK, 1)
        for i in range(4):
            s.fill(x + w // 2 - 22, y + 11 + i * 9, 26, 2, GREY)
        s.fill(x + w // 2 - 22, y + 11, 26, 2, RED)
        s.fill(x + w // 2 - 22, y + 20, 26, 2, RED)
        pts = [(x + 8, y + h - 12), (x + w // 3, y + h - 20),
               (x + 2 * w // 3, y + 12), (x + w - 8, y + 6)]
        for i in range(len(pts) - 1):
            s.segment(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1],
                      RED, 2)
        s.disc(x + w - 8, y + 6, 3, RED)
    elif kind == "stocks":
        # A falling market line over candlesticks, a red arrow down.
        s.fill(x, y, w, h, (200, 216, 232))
        for i, (bx, bh) in enumerate(((10, 10), (28, 14), (46, 8))):
            col = GREEN if i == 0 else RED
            s.fill(x + bx, y + h - 12 - bh, 10, bh, col)
            s.fill(x + bx + 4, y + h - 14 - bh, 2, 4, col)
        pts = [(x + 8, y + 10), (x + w // 3, y + 16),
               (x + 2 * w // 3, y + h - 16), (x + w - 10, y + h - 8)]
        for i in range(len(pts) - 1):
            s.segment(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1],
                      RED, 3)
        s.fill_poly([(x + w - 10, y + h - 8), (x + w - 22, y + h - 8),
                     (x + w - 10, y + h - 20)], RED)
        s.disc(x + 8, y + 10, 3, RED)
    elif kind == "treaty":
        # Two flags, a signed document, and clasped hands below.
        s.fill(x, y, w, h, (232, 220, 196))
        for i, col in enumerate((BLUE, GREEN)):
            fx = x + 16 + i * (w - 32) // 2
            s.fill(fx, y + 4, 2, 20, INK)
            s.fill(fx + 2, y + 4, 18, 10, col)
        s.fill(x + w // 2 - 26, y + 18, 52, 14, WHITE)
        s.frame(x + w // 2 - 26, y + 18, 52, 14, INK, 1)
        s.fill(x + w // 2 - 20, y + 22, 30, 2, INK)
        s.fill(x + w // 2 - 20, y + 27, 22, 2, GREY)
        s.disc(x + w // 2 - 12, y + h - 12, 7, (200, 170, 130))
        s.disc(x + w // 2 + 12, y + h - 12, 7, (170, 130, 110))
        s.fill(x + w // 2 - 6, y + h - 16, 12, 8, (200, 170, 130))
    elif kind == "football":
        # A green pitch, a goal, and a ball heading for the net.
        s.fill(x, y, w, h, (60, 140, 80))
        s.fill(x, y + h // 2, w, 2, WHITE)
        s.disc(x + w // 2, y + h // 2, 8, WHITE)
        s.hoop(x + w // 2, y + h // 2, 8, WHITE, 1)
        s.fill(x + w - 26, y + 8, 18, h - 16, WHITE)
        s.frame(x + w - 26, y + 8, 18, h - 16, INK, 1)
        for gy in range(12, h - 8, 8):
            s.fill(x + w - 26, y + gy, 18, 1, GREY)
        s.disc(x + w // 3, y + h - 14, 6, WHITE)
        s.fill(x + w // 3 - 1, y + h - 15, 3, 3, INK)
        s.segment(x + w // 3, y + h - 14, x + w - 26, y + h // 2, WHITE, 1)


# ---------------------------------------------------------------------------
# Map: equirectangular projection, simplified continents, numbered pins.
# ---------------------------------------------------------------------------

def project(lon, lat, mx, my, mw, mh):
    px = mx + (lon + 170.0) / 360.0 * mw
    py = my + (85.0 - lat) / 145.0 * mh
    return px, py


def pin_positions(mx, my, mw, mh):
    """Pixel positions for all 40 pins, with clusters spread on arcs and
    a short repulsion pass so no two pins hide each other's numbers."""
    all_stories = [(n, lat, lon, region) for (n, _h, _p, region, lat, lon, _s, _b, _v)
                   in HIGHLIGHTS]
    all_stories += [(n, lat, lon, region) for (n, _h, _p, region, lat, lon, _s)
                    in ALSO_ON]
    clustered = {}
    for cl in CLUSTERS:
        cx, cy = project(cl["centre"][1], cl["centre"][0], mx, my, mw, mh)
        n = len(cl["members"])
        for i, num in enumerate(cl["members"]):
            ang = -1.5708 + 6.28318 * i / n
            clustered[num] = (cx + cl["radius"] * _cosine(ang),
                              cy + cl["radius"] * _sine(ang),
                              cx, cy)
    pos = {}
    true_xy = {}
    for num, lat, lon, region in all_stories:
        tx, ty = project(lon, lat, mx, my, mw, mh)
        true_xy[num] = (tx, ty)
        if num in clustered:
            px, py, _cx, _cy = clustered[num]
            pos[num] = [px, py]
        else:
            pos[num] = [tx, ty]
    # Repulsion: keep pin centres at least 16 px apart.
    order = sorted(pos)
    for _ in range(14):
        for i in range(len(order)):
            for j in range(i + 1, len(order)):
                a = pos[order[i]]
                b = pos[order[j]]
                dx = b[0] - a[0]
                dy = b[1] - a[1]
                d2 = dx * dx + dy * dy
                if d2 < 16.0 * 16.0 and d2 > 0.01:
                    d = d2 ** 0.5
                    push = (16.0 - d) / 2.0
                    ux, uy = dx / d, dy / d
                    a[0] -= ux * push
                    a[1] -= uy * push
                    b[0] += ux * push
                    b[1] += uy * push
        for num in order:
            p = pos[num]
            p[0] = max(mx + 9, min(mx + mw - 9, p[0]))
            p[1] = max(my + 9, min(my + mh - 9, p[1]))
    regions = {num: region for num, _lat, _lon, region in all_stories}
    return pos, true_xy, regions


def draw_map(s, mx, my, mw, mh):
    s.fill(mx, my, mw, mh, SEA)
    for poly in CONTINENTS:
        pts = [(int(round(mx + (lon + 170.0) / 360.0 * mw)),
                int(round(my + (85.0 - lat) / 145.0 * mh))) for lon, lat in poly]
        s.fill_poly(pts, LAND)
        for i in range(len(pts)):
            x0, y0 = pts[i]
            x1, y1 = pts[(i + 1) % len(pts)]
            s.segment(x0, y0, x1, y1, COAST, 1)
    pos, true_xy, regions = pin_positions(mx, my, mw, mh)
    # Leader lines from spread pins back to their true city dot.
    for num in sorted(pos):
        px, py = pos[num]
        tx, ty = true_xy[num]
        if abs(px - tx) > 3 or abs(py - ty) > 3:
            s.segment(int(round(tx)), int(round(ty)), int(round(px)),
                      int(round(py)), (90, 90, 90), 1)
            s.disc(int(round(tx)), int(round(ty)), 2, INK)
    for num in sorted(pos):
        px, py = pos[num]
        cx, cy = int(round(px)), int(round(py))
        colour = REGION_PAINT.get(regions[num], NAVY)
        s.disc(cx, cy, 7, colour)
        s.hoop(cx, cy, 7, WHITE, 1)
        label = str(num)
        tw = measure(SB9, label)
        s.write(cx - tw // 2, cy + 3, SB9, label, WHITE)
        record("pin %d" % num, cx - 7, cy - 7, cx + 7, cy + 7)
    s.frame(mx, my, mw, mh, INK, 1)
    record("map", mx, my, mx + mw, my + mh)
    return pos


def draw_lead(s, x, y, w, h, story):
    num, headline, place, region, _lat, _lon, source, body, kind = story
    colour = REGION_PAINT.get(region, NAVY)
    s.frame(x, y, w, h, INK, 1)
    s.fill(x + 1, y + 1, w - 2, 19, colour)
    label, src = shorten_label(num, place, source, SB9, SB8, w - 6)
    s.write(x + 8, y + 15, SB9, label, WHITE)
    sw = measure(SB8, src)
    s.write(x + w - 8 - sw, y + 14, SB8, src, WHITE)
    paint_picture(s, kind, x + 1, y + 20, w - 2, 44)
    lines = wrap(PF24, headline, w - 12)
    yy = y + 88
    for ln in lines[:2]:
        s.write(x + 6, yy, PF24, ln, INK)
        yy += 25
    record("lead %d headline" % num, x + 6, y + 88 - 24,
           x + 6 + max(measure(PF24, ln) for ln in lines[:2]), yy - 25 + 6)
    body_lines = wrap(SR11, body, w - 12)
    yy = y + 138
    for ln in body_lines[:5]:
        s.write(x + 6, yy, SR11, ln, INK)
        yy += 13
    record("lead %d body" % num, x + 6, y + 138 - 11,
           x + 6 + max(measure(SR11, ln) for ln in body_lines[:5]), yy - 13 + 4)
    record("lead %d card" % num, x, y, x + w, y + h)


def draw_small(s, x, y, w, h, story):
    num, headline, place, region, _lat, _lon, source, body, kind = story
    colour = REGION_PAINT.get(region, NAVY)
    s.frame(x, y, w, h, INK, 1)
    s.fill(x + 1, y + 1, w - 2, 15, colour)
    label, src = shorten_label(num, place, source, SB8, SB8, w - 6)
    s.write(x + 6, y + 12, SB8, label, WHITE)
    sw = measure(SB8, src)
    s.write(x + w - 6 - sw, y + 12, SB8, src, WHITE)
    paint_picture(s, kind, x + 1, y + 16, w - 2, 32)
    lines = wrap(PF15, headline, w - 12)
    yy = y + 66
    for ln in lines[:3]:
        s.write(x + 6, yy, PF15, ln, INK)
        yy += 17
    n_head = min(len(lines), 3)
    record("small %d headline" % num, x + 6, y + 66 - 15,
           x + 6 + max(measure(PF15, ln) for ln in lines[:3]), yy - 17 + 5)
    body_lines = wrap(SR11, SMALL_BODY[num], w - 12)
    yy = y + 66 + 17 * (n_head - 1) + 13
    n_body = 0
    for ln in body_lines:
        if yy > y + 129 or n_body >= 3:
            break
        s.write(x + 6, yy, SR11, ln, INK)
        yy += 12
        n_body += 1
    if n_body:
        record("small %d body" % num, x + 6, y + 66 + 17 * (n_head - 1) + 2,
               x + 6 + max(measure(SR11, ln) for ln in body_lines[:n_body]),
               yy - 12 + 4)
    record("small %d card" % num, x, y, x + w, y + h)


def draw():
    s = Sheet(PAGE_W, PAGE_H, PAPER)
    x0, x1 = 10, 1014
    cw = x1 - x0

    # Top band.
    s.fill(x0, 8, cw, 20, INK)
    s.write(x0 + 8, 22, SB10, "THE WORLD IN ONE DAY", WHITE, track=2)
    right = "40 STORIES FROM ONE DAY"
    s.write(x1 - 8 - measure(SB10, right, 2), 22, SB10, right, WHITE, track=2)
    record("top band", x0, 8, x1, 28)

    # Masthead and kicker.
    s.write(PAGE_W // 2, 94, PF62, MASTHEAD, INK, align="center")
    record("masthead", PAGE_W // 2 - measure(PF62, MASTHEAD) // 2, 94 - 62,
           PAGE_W // 2 + measure(PF62, MASTHEAD) // 2, 94 + 6)
    s.write(PAGE_W // 2, 114, SR12, KICKER, INK, align="center")
    record("kicker", PAGE_W // 2 - measure(SR12, KICKER) // 2, 114 - 12,
           PAGE_W // 2 + measure(SR12, KICKER) // 2, 114 + 4)
    s.fill(x0, 122, cw, 2, GOLD)
    s.fill(x0, 125, cw, 1, INK)

    # The day in UTC.
    ty = 130
    s.fill(x0, ty, 104, 48, INK)
    s.write(x0 + 52, ty + 20, SB10, "THE DAY", WHITE, align="center")
    s.write(x0 + 52, ty + 34, SB10, "IN UTC", WHITE, align="center")
    cell_w = (x1 - (x0 + 108)) / 6.0
    for i, (t, label) in enumerate(TIMELINE):
        cx = x0 + 108 + i * cell_w
        if i:
            s.vbar(int(round(cx)), ty + 4, 40, PALE, 1)
        s.write(int(round(cx)) + 6, ty + 12, SB10, t, RED)
        lines = label.split("\n")
        yy = ty + 24
        for ln in lines:
            s.write(int(round(cx)) + 6, yy, SR10, ln, INK)
            yy += 11
        record("timeline %d" % i, int(round(cx)) + 6, ty + 2,
               int(round(cx)) + 6 + max(measure(SR10, ln) for ln in lines),
               yy - 11 + 4)
    record("timeline block", x0, ty, x1, ty + 48)

    # Stat boxes.
    sy = 184
    for i, (big, label) in enumerate(STATS):
        bx = x0 + i * 168
        s.frame(bx, sy, 164, 50, INK, 1)
        s.write(bx + 82, sy + 26, PF26, big, INK, align="center")
        lns = label.split("\n")
        yy = sy + 38
        for ln in lns:
            s.write(bx + 82, yy, SB8, ln, GREY, align="center")
            yy += 10
        record("stat %d" % i, bx, sy, bx + 164, sy + 50)

    # Region bar: counts, then a segmented colour bar.
    s.write(PAGE_W // 2, 250, SB9, REGION_BAR, INK, align="center")
    record("region bar", PAGE_W // 2 - measure(SB9, REGION_BAR) // 2, 250 - 9,
           PAGE_W // 2 + measure(SB9, REGION_BAR) // 2, 250 + 3)
    counts = [("AMERICAS", 10, BLUE), ("EUROPE", 9, RED),
              ("MIDDLE EAST", 7, GOLD), ("AFRICA", 6, TEAL),
              ("EAST ASIA", 5, GREEN), ("SE ASIA", 1, ORANGE),
              ("SOUTH ASIA", 1, PURPLE), ("OCEANIA", 1, MAUVE)]
    bx = x0
    for _name, n, colour in counts:
        seg = int(round(cw * n / 40.0))
        s.fill(bx, 256, seg, 5, colour)
        bx += seg

    # Highlights: 3 large, then 10 small in two rows of five.
    lead_y, lead_h = 266, 204
    for i, story in enumerate(HIGHLIGHTS[:3]):
        draw_lead(s, x0 + i * 337, lead_y, 330, lead_h, story)
    small_y1, small_h = 474, 136
    for i, story in enumerate(HIGHLIGHTS[3:8]):
        draw_small(s, x0 + i * 202, small_y1, 196, small_h, story)
    small_y2 = 614
    for i, story in enumerate(HIGHLIGHTS[8:13]):
        draw_small(s, x0 + i * 202, small_y2, 196, small_h, story)

    # Section headers for the map and the further stories.
    map_x, map_y, map_w, map_h = x0, 772, 372, 176
    s.write(x0, 768, SB13, "WHERE IT HAPPENED", INK, track=1)
    record("map header", x0, 768 - 13,
           x0 + measure(SB13, "WHERE IT HAPPENED", 1), 768 + 4)
    legend = "PINS 1\u201340 \u00b7 COLOUR = REGION"
    s.write(map_x + map_w - measure(SB8, legend), 768, SB8, legend, GREY)
    record("map legend", map_x + map_w - measure(SB8, legend), 768 - 8,
           map_x + map_w, 768 + 3)
    s.write(394, 768, SB13, ALSO_HEADER, INK, track=1)
    record("also header", 394, 768 - 13,
           394 + measure(SB13, ALSO_HEADER, 1), 768 + 4)

    # Map (left) and the 27 further stories (right, two columns).
    draw_map(s, map_x, map_y, map_w, map_h)
    col1 = ALSO_ON[:14]
    col2 = ALSO_ON[14:]
    for col_x, items in ((394, col1), (700, col2)):
        yy = map_y + 11
        for num, headline, place, _region, _lat, _lon, _src in items:
            line = "%d %s \u2014 %s" % (num, headline, place)
            s.write(col_x, yy, SR10, line, INK)
            yy += 12
        record("also col %d" % col_x, col_x, map_y + 11 - 10,
               col_x + max(measure(SR10, "%d %s \u2014 %s" % (n, h, p))
                           for n, h, p, _r, _la, _lo, _s in items),
               yy - 12 + 4)

    # Date check box: sized from the measured wrapped text.
    dy = 952
    s.frame(x0, dy, cw, 40, RED, 1)
    s.write(x0 + 8, dy + 15, SB9, "DATE CHECK", RED)
    dc_lines = wrap(SR10, DATE_CHECK, 886)
    yy = dy + 12
    for ln in dc_lines:
        s.write(x0 + 118, yy, SR10, ln, INK)
        yy += 12
    record("date check", x0, dy, x1, dy + 40)
    record("date check text", x0 + 118, dy + 2,
           x0 + 118 + max(measure(SR10, ln) for ln in dc_lines), yy - 12 + 4)

    # How we checked footer.
    fy = 996
    s.write(x0, fy + 12, SB9, "HOW WE CHECKED", INK)
    hw_lines = wrap(SR10, HOW_WE_CHECKED, 854)
    yy = fy + 10
    for ln in hw_lines:
        s.write(x0 + 150, yy, SR10, ln, INK)
        yy += 12
    record("footer", x0, fy, x1,
           yy - 12 + 4 if hw_lines else fy + 12)
    record("footer text", x0 + 150, fy,
           x0 + 150 + max(measure(SR10, ln) for ln in hw_lines), yy - 12 + 4)

    return s


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    sheet = draw()
    size = save_png(sheet, path)
    sys.stdout.write("wrote %s (%d bytes)\n" % (path, size))


if __name__ == "__main__":
    main()
